+/****************************************************************************
+ * 名称: run_trace
+ *
+ * 描述: 动作轨迹观测模式（真机诊断用）
+ *
+ * 【背景】用户观察：做右甩时"刚出发"就被识别。怀疑当前"每 50ms 判定一次"
+ * 的机制会在动作起步阶段（X 主导、Y 尚小）抢先判定。
+ * 本模式不改变任何判定逻辑，只统计【整个动作的峰值特征】，
+ * 用于回答："用完整动作峰值（而非起步瞬间）能否区分三种手势？"
+ *
+ * 输出格式：
+ *   [TRACE] 时长 X窗  |Y|峰值 xxx  Y符号 ±  X峰值 xxx  加速度偏离 xxx
+ ****************************************************************************/
+static void run_trace(void)
+{
+  struct imu_frame_s f;
+  struct gesture_event_s ev;
+  int frame = 0;
+
+  printf("\n[TRACE] 动作轨迹观测模式（判定逻辑不变，仅记录峰值）\n");
+  printf("[TRACE] 每完成一个动作会打印一行统计；输入 q 回车 或 Ctrl+C 退出\n\n");
+
+  console_nonblock();
+
+  while (1)
+    {
+      if (exit_key_pressed())
+        {
+          printf("\n[TRACE] 收到退出键，停止。\n");
+          break;
+        }
+
+      if (imu_sample(&f) != 0)
+        {
+          usleep(5000);
+          frame++;
+          continue;
+        }
+
+      f.timestamp_us = (uint32_t)(frame * 1000000ULL / GESTURE_FS_HZ);
+      frame++;
+
+      /* 正常喂给识别器（保持行为一致，事件仍会照常上报） */
+      gesture_feed(&f, &ev);
+
+      if (ev.type != GESTURE_NONE)
+        {
+          printf("[TRACE] 判定上报: %s 置信度 %.2f\n",
+                 gesture_type_name(ev.type), ev.confidence);
+        }
+
+      /* 打印「完整动作」的峰值统计（动作结束后才有） */
+      {
+        float t_maxY, t_maxX, t_dev;
+        int   t_sign, t_win;
+
+        if (gesture_get_motion_trace(&t_maxY, &t_sign, &t_maxX,
+                                     &t_dev, &t_win))
+          {
+            printf("[TRACE] 动作峰值: 时长 %d 窗(%dms) | "
+                   "|Y|峰值 %.0f  Y符号 %s | X峰值 %.0f | 加速偏离 %.2f\n",
+                   t_win, t_win * GESTURE_STEP_MS,
+                   t_maxY, (t_sign > 0) ? "+" : "-",
+                   t_maxX, t_dev);
+          }
+      }
+
+      usleep(5000);
+    }
+
+  console_restore();
 }

