+  static uint32_t stamps[TIMING_MAX_N];   /* 静态分配，避免大栈占用 */
+  int    got = 0;
+  int    i;
+
+  if (n_frames <= 0)      n_frames = 5000;
+  if (n_frames > TIMING_MAX_N) n_frames = TIMING_MAX_N;
+
+  printf("\n[TIMING] 采样抖动测量模式\n");
+  printf("[TIMING] 将连续采集 %d 帧（约 %.1f 秒），请保持板子静止\n\n",
+         n_frames, n_frames * 4.8f / 1000.0f);
+  printf("[TIMING] 采集中");
+
+  for (i = 0; i < n_frames; i++)
+    {
+      if (imu_sample(&f) != 0)
+        {
+          usleep(1000);
+          continue;
+        }
+      stamps[got++] = f.hw_timestamp;
+
+      if ((i % 500) == 0)
+        {
+          printf(".");
+        }
+      usleep(5000);   /* 按 208Hz 节拍 */
+    }
+  printf(" 完成\n\n");
+
+  if (got < 10)
+    {
+      printf("[TIMING] 采样点不足（%d），无法统计。\n", got);
+      return;
+    }
+
+  /* ---- 计算相邻间隔（处理 24 位回绕） ---- */
+  {
+    double  sum = 0.0, sumsq = 0.0;
+    float   dmin_ms = 1e9f, dmax_ms = 0.0f;
+    uint32_t prev = stamps[0];
+    int     n = 0;
+    float   dev_max = 0.0f;
+    float   mean;
+    float   sigma;
+
+    /* 分位数用的直方图（1 ms 一档，覆盖 0~20 ms） */
+    static int hist[24];
+    memset(hist, 0, sizeof(hist));
+
+    for (i = 1; i < got; i++)
+      {
+        uint32_t cur  = stamps[i];
+        uint32_t diff = (cur >= prev) ? (cur - prev)
+                                      : (cur + TIMING_WRAP_MASK + 1u - prev);
+        float diff_ms = (float)diff * TIMING_LSB_US / 1000.0f;
+
+        prev = cur;
+        n++;
+
+        sum   += diff_ms;
+        sumsq += (double)diff_ms * (double)diff_ms;
+
+        if (diff_ms < dmin_ms) dmin_ms = diff_ms;
+        if (diff_ms > dmax_ms) dmax_ms = diff_ms;
+
+        {
+          int b = (int)diff_ms;
+          if (b >= 0 && b < 24) hist[b]++;
+        }
+      }
+
+    mean = (float)(sum / (double)n);
+    {
+      double var = (sumsq / (double)n) - (double)mean * (double)mean;
+      if (var < 0.0) var = 0.0;
+      sigma = (float)sqrt(var);
+    }
+
+    /* 最大偏差 = 与均值偏差的绝对值最大者 */
+    {
+      float a = fabsf(dmax_ms - mean);
+      float b = fabsf(mean - dmin_ms);
+      dev_max = (a > b) ? a : b;
+    }
+
+    /* ---- 输出统计 ---- */
+    printf("============================================================\n");
+    printf("采样抖动测量结果（数据源：芯片硬件时间戳，LSB=25μs）\n");
+    printf("============================================================\n");
+    printf("  采样点数            : %d\n", got);
+    printf("  有效间隔数          : %d\n", n);
+    printf("  标称采样间隔        : 4807.7 μs  (208 Hz)\n");
+    printf("  实际平均间隔        : %.1f μs\n", mean * 1000.0f);
+    printf("  实际平均采样率      : %.2f Hz\n", 1000.0f / mean);
+    printf("\n");
+    printf("  采样间隔标准差 σ    : %.1f μs   目标 <500  → %s\n",
+           sigma * 1000.0f,
+           (sigma * 1000.0f < 500.0f) ? "达标" : "未达标");
+    printf("  最大间隔偏差 Δt_max : %.1f μs   目标 <2000 → %s\n",
+           dev_max * 1000.0f,
+           (dev_max * 1000.0f < 2000.0f) ? "达标" : "未达标");
+    printf("  间隔范围            : %.1f ~ %.1f μs\n",
+           dmin_ms * 1000.0f, dmax_ms * 1000.0f);
+
+    /* 分位数 */
+    {
+      int cum = 0, p1 = -1, p50 = -1, p99 = -1;
+      int t1 = (int)(n * 0.01f), t50 = (int)(n * 0.50f), t99 = (int)(n * 0.99f);
+
+      for (i = 0; i < 24; i++)
+        {
+          cum += hist[i];
+          if (p1  < 0 && cum >= t1)  p1  = i;
+          if (p50 < 0 && cum >= t50) p50 = i;
+          if (p99 < 0 && cum >= t99) p99 = i;
+        }
+      printf("  P1 / P50 / P99      : %d / %d / %d ms\n", p1, p50, p99);
+    }
+
+    printf("============================================================\n");
+    printf("说明：以上数据由芯片内部时间戳计数器测得，反映 ODR 的真实抖动，\n");
+    printf("      不含任务调度与 I2C 传输的软件开销。\n");
+    printf("============================================================\n\n");
+  }
 }

